def hydrate_time(nanoseconds, tz=None):
    if nanoseconds < 0:
        raise ValueError("Negative nanoseconds are not supported")
    if tz is None:
        tz = datetime.now().tzname
    days, seconds, microseconds = divmod(nanoseconds, 86400000000)
    return datetime.fromtimestamp((days * 24 + seconds) / 60.0, tz=tz)

