def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def decorator(func):
        if func is None:
            return decorator

        cache = {}
        accessed = {}
        min_accessed_time = 0

        def get_key(*args, **kwargs):
            return hash((args, tuple(kwargs.items())))

        def update_accessed_time():
            nonlocal min_accessed_time
            current_time = timer()
            for key in accessed:
                if current_time - accessed[key] > ttl:
                    del accessed[key]
                elif current_time < min_accessed_time:
                    min_accessed_time = current_time

        def _memoized_call(func, args, cache):
            if id(func) in cache:
                return cache[id(func)]
            result = func(*args)
            cache[id(func)] = result
            return result

        def put(*args, **kwargs):
            key = get_key(*args, **kwargs)
            # Update the lru order if the key already exists
            if key in accessed:
                update_accessed_time()
            # Remove the least recently used key if the cache is full
            if len(cache) >= maxsize:
                min_accessed_time = timer()
                while key in accessed:
                    accessed.popitem(last=False)
            accessed[key] = timer()

        def lifespan(*args, **kwargs):
            key = get_key(*args, **kwargs)
            return accessed.get(key, None)

        def clear():
            cache.clear()
            accessed.clear()

        memo = _memoized_call(func, args, cache)
        memo.put = put
        memo.lifespan = lifespan
        memo.clear = clear

        return memo

    return decorator

