def _validate_labels(labels: Dict[str, Any]) -> None:
    regexes = {"key": r"^[a-zA-Z0-9]+$", "value": r".+"}
    messages = []
    for label in labels.items():
        label_name, label_value = label
        if label_name in regexes:
            regex = regexes[label_name]
            if not isinstance(label_value, str):
                message = f"Label key '{label_name}' does not match the regular expression '{regex}'."
                messages.append({"label_name": message})
        else:
            message = f"Label key '{label_name}' is not a valid key."
            messages.append({"label_name": message})
    if messages:
        raise ValidationError(messages)

