    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        path = pfs.validate_path(path, pfs.PY_FS_S3)
    except KeyError:
        path = path

    if not path:
        raise EmptyPathError(f'Path {path} is empty')

    try:
        initial_path = pfs.get_root(path)
        root_dir = initial_path / path
        pfs.mkdir(root_dir)
