def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if prior is None:
        raise ValueError('Prior cannot be None')

    if isinstance(prior, InventoryValidator) == False:
        raise ValueError('Prior must be an InventoryValidator object')

    if self._inventory == None:
        raise ValueError('self.inventory must not be None')

    if self._inventory.length != self._parameters.length:
        raise ValueError('self.inventory length must match self.parameters length')

    if self._parameters.get_index(self._id) == -1:
        raise ValueError('self.id is not in self.parameters index list')

    if self._presentation != prior._presentation:
        raise ValueError('self.presentation must match prior.presentation')

    if prior._table is None:
        raise ValueError('prior table cannot be None')

    if prior._table.length != self._presentation.length:
        raise ValueError('prior table length must match self.presentation length')

    if prior._table.get_index(self._presentation) == -1:
        raise ValueError('self.presentation is not in prior._table index list')

    if not self._attributesistributed:
        raise ValueError('self._attributes distributed must be True')

    if not prior._attributes Distributed:
        raise ValueError('prior._attributes distributed must be True')

    return True

