def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized_attrs = {}

    for attr_name, attr_value in self.__dict__.items():
        if isinstance(attr_value, relativedelta):
            normalized_attrs[attr_name] = attr_value.__dict__.copy()
            for attr_subname, attr_subvalue in normalized_attrs[attr_name].items():
                if attr_subname == 'days':
                    normalized_attrs[attr_name][attr_subname] = int(attr_subvalue)
                elif attr_subname in ['hours', 'minutes', 'seconds']:
                    normalized_attrs[attr_name][attr_subname] = int(attr_subvalue)
                elif attr_subname in ['milliseconds', 'microseconds', 'nanoseconds']:
                    normalized_attrs[attr_name][attr_subname] = int(attr_subvalue) * 10 ** attr_subname[-1]
        else:
            normalized_attrs[attr_name] = attr_value

    return relativedelta(**normalized_attrs)

