def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        import platform as _platform
        if _platform.system() == 'Windows':
            platform = 0  # Windows/CMD
        elif _platform.system() == 'Linux' or _platform.system() == 'Darwin':
            platform = 1  # POSIX

    if platform not in [0, 1]:
        raise ValueError("Invalid platform value. Must be 0 (Windows/CMD) or 1 (POSIX).")

    # Regular expression for parsing command lines
    lexp = r'[^\s]+|"[^"]*"|\'[^\']*\'' if platform == 0 else r'[^\s]+|\'[^\']*\''|"[^"]*'

    return re.findall(lexp, s.replace('  ', ' '))

