def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    if prop == RDFS.subClassOf:
        # Check all parents directly to root
        for parent in graph.objects(None, prop):
            if parent not in roots:
                roots.add(parent)
                roots.update(find_roots(None, prop, roots))
        # Check transitive closure
        for child in graph.subjects(prop, None):
            roots.update(find_roots(graph, prop, roots))
        return roots
    elif prop == SKOS.broader:
        # Check all parents directly to root
        for parent in graph.objects(None, prop):
            if parent not in roots:
                roots.add(parent)
                roots.update(find_roots(None, prop, roots))
        # Check transitive closure
        for child in graph.subjects(prop, None):
            roots.update(find_roots(graph, prop, roots))
        return roots
    else:
        raise ValueError(f"Unsupported property: {prop}")

