def parse_xrd_document(document):
    """
    Parse Diaspora webfinger in JSON format (new).
    """
    try:
        json_data = json.loads(document)
        if "identities" not in json_data:
            raise ValueError("No identities field in JSON content")
        hcard_url = json_data["identities"][0].get("hcard-embed", None)
        if not hcard_url:
            raise ValueError("No hcard-embed link in identity")
        return {"hcard_url": hcard_url}
    except Exception as e:
        print(f"Failed to parse webfinger: {e}")
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        url = f"https://{handle}/.well-known/webfinger?resource=acct:{handle}"
        response = requests.get(url, timeout=10)
        return response.text
    except requests.RequestException:
        return None

import os

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    :param settings_dirs: paths to the settings directories
    :param spec_option: spec option to determine the type of settings
    :return: a list of file names
    """
    file_names = []
    for directory in settings_dirs:
        if os.path.isdir(directory):
            file_names.extend([
                os.path.join(directory, file)
                for file in os.listdir(directory)
                if file.endswith('.ini') and spec_option in file
            ])
    return file_names

