class IRValidator:
    def __init__(self, default_schema_file, loader=yaml.FullLoader):
        self.default_schema_file = default_schema_file
        self.loader = loader
        self.valid_data = None
        self.errors = []

    @classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content must be supplied")

        try:
            data = yaml.safe_load(spec_content, Loader=cls.loader)

        except yaml.YAMLException as e:
            raise IRValidatorException("There was a problem parsing the YAML content.\n" + e.__str__())

        if 'required' not in data:
            raise IRValidatorException("Required fields are missing in spec file.")

        for field in data['required']:
            if field not in data:
                raise IRValidatorException(f"Missing required field in spec file: {field}")

        return data

def _include_groups(self, parser_dict):
